=<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Booking Confirmation</title>
</head>

<body style="
  margin:0;
  padding:0;
  background:#f5f5f5;
  font-family:Arial, Helvetica, sans-serif;
  color:#222222;
">

  <table width="100%" cellpadding="0" cellspacing="0" border="0"
         style="background:#f5f5f5; padding:30px 15px;">

    <tr>
      <td align="center">

        <!-- Main Container -->
        <table width="550" cellpadding="0" cellspacing="0" border="0"
               style="
                 max-width:550px;
                 width:100%;
                 background:#ffffff;
                 border-radius:12px;
                 overflow:hidden;
               ">

          <!-- HEADER -->
          <tr>
            <td style="
              background:#111111;
              padding:32px 28px;
              color:#ffffff;
            ">

              <div style="
                display:inline-block;
                border:1px solid #555555;
                border-radius:20px;
                padding:7px 13px;
                font-size:11px;
                font-weight:bold;
                letter-spacing:.5px;
                color:#dddddd;
              ">
                BOOKING CONFIRMED
              </div>

              <h1 style="
                margin:20px 0 10px 0;
                font-size:28px;
                line-height:1.15;
                color:#ffffff;
              ">
                You're officially<br>
                on the guest list.
              </h1>

              <p style="
                margin:0;
                color:#aaaaaa;
                font-size:14px;
                line-height:1.5;
              ">
                Your reservation for
                <strong style="color:#ffffff;">
                  {{$json.eventName}}
                </strong>
                has been successfully confirmed.
              </p>

            </td>
          </tr>


          <!-- CONTENT -->
          <tr>
            <td style="padding:35px 28px 25px 28px;">

              <p style="
                margin:0 0 12px 0;
                color:#777777;
                font-size:14px;
              ">
                Hello,
              </p>

              <h2 style="
                margin:0 0 22px 0;
                font-size:24px;
                color:#222222;
              ">
                {{$json.name}}
              </h2>

              <p style="
                margin:0 0 25px 0;
                color:#555555;
                font-size:14px;
                line-height:1.6;
              ">
                We're excited to confirm your place at
                <strong>{{$json.eventName}}</strong>.
                Keep this email as your booking confirmation.
              </p>


              <!-- DETAILS TABLE -->
              <table width="100%" cellpadding="0" cellspacing="0" border="0"
                     style="
                       border:1px solid #e5e5e5;
                       border-radius:10px;
                       overflow:hidden;
                     ">

                <!-- EVENT -->
                <tr>
                  <td style="
                    padding:16px;
                    background:#fafafa;
                    border-bottom:1px solid #e5e5e5;
                    color:#888888;
                    font-size:12px;
                    font-weight:bold;
                  ">
                    EVENT
                  </td>

                  <td align="right" style="
                    padding:16px;
                    background:#fafafa;
                    border-bottom:1px solid #e5e5e5;
                    color:#111111;
                    font-size:13px;
                    font-weight:bold;
                  ">
                    Arab Automators Event
                  </td>
                </tr>


                <!-- ATTENDEE -->
                <tr>
                  <td style="
                    padding:16px;
                    border-bottom:1px solid #e5e5e5;
                    color:#888888;
                    font-size:12px;
                    font-weight:bold;
                  ">
                    ATTENDEE
                  </td>

                  <td align="right" style="
                    padding:16px;
                    border-bottom:1px solid #e5e5e5;
                    color:#111111;
                    font-size:13px;
                    font-weight:bold;
                  ">
                    {{$json.name}}
                  </td>
                </tr>


                <!-- EMAIL -->
                <tr>
                  <td style="
                    padding:16px;
                    background:#fafafa;
                    border-bottom:1px solid #e5e5e5;
                    color:#888888;
                    font-size:12px;
                    font-weight:bold;
                  ">
                    EMAIL
                  </td>

                  <td align="right" style="
                    padding:16px;
                    background:#fafafa;
                    border-bottom:1px solid #e5e5e5;
                    font-size:13px;
                  ">
                    <a href="mailto:{{$json.email}}"
                       style="
                         color:#2864c7;
                         font-weight:bold;
                         text-decoration:underline;
                       ">
                      {{$json.email}}
                    </a>
                  </td>
                </tr>


                <!-- DATE -->
                <tr>
                  <td style="
                    padding:16px;
                    color:#888888;
                    font-size:12px;
                    font-weight:bold;
                  ">
                    DATE
                  </td>

                  <td align="right" style="
                    padding:16px;
                    color:#111111;
                    font-size:13px;
                    font-weight:bold;
                  ">
                    {{$json.date}}
                  </td>
                </tr>

              </table>


              <!-- STATUS -->
              <table width="100%" cellpadding="0" cellspacing="0" border="0"
                     style="
                       margin-top:24px;
                       border:1px dashed #cccccc;
                       border-radius:10px;
                     ">

                <tr>
                  <td align="center" style="padding:22px;">

                    <div style="
                      color:#999999;
                      font-size:11px;
                      font-weight:bold;
                      letter-spacing:1px;
                      margin-bottom:8px;
                    ">
                      RESERVATION STATUS
                    </div>

                    <div style="
                      color:#222222;
                      font-size:15px;
                      font-weight:bold;
                    ">
                      ✓ CONFIRMED
                    </div>

                  </td>
                </tr>

              </table>


              <!-- FOOTER MESSAGE -->
              <p style="
                margin:25px 8px 5px 8px;
                text-align:center;
                color:#888888;
                font-size:12px;
                line-height:1.5;
              ">
                Please keep this confirmation email available when attending
                the event. Further event details and updates may be sent to
                your registered email.
              </p>

            </td>
          </tr>


          <!-- FOOTER -->
          <tr>
            <td style="
              background:#fafafa;
              padding:20px;
              text-align:center;
              color:#aaaaaa;
              font-size:11px;
            ">
              © 2026 Arab Automators Event
            </td>
          </tr>

        </table>

      </td>
    </tr>

  </table>

</body>
</html>
